// Payment statuses.
const (
	StatusCreated   Status = "CREATED"
	StatusPending   Status = "PENDING"
	StatusSucceeded Status = "SUCCEEDED"
	StatusDeclined  Status = "DECLINED"
	StatusRefunded  Status = "REFUNDED"
	StatusCanceled  Status = "CANCELED"
)

var allStatuses = []Status{StatusCreated, StatusPending, StatusSucceeded, StatusDeclined, StatusRefunded, StatusCanceled}

// ParseStatus parses a status name, case-insensitively.
func ParseStatus(s string) (Status, error) {
	up := Status(strings.ToUpper(strings.TrimSpace(s)))
	for _, st := range allStatuses {
		if st == up {
			return st, nil
		}
	}
	return "", fmt.Errorf("%w: unknown status %q", ErrInvalidInput, s)
}

// Final reports whether no further transitions are possible from s.
func (s Status) Final() bool {
	return s == StatusDeclined || s == StatusRefunded || s == StatusCanceled
}

