func TestStatusFinal(t *testing.T) {
	tests := []struct {
		status Status
		want   bool
	}{
		{StatusCreated, false},
		{StatusPending, false},
		{StatusSucceeded, false},
		{StatusDeclined, true},
		{StatusRefunded, true},
		{StatusCanceled, true},
	}
	for _, tt := range tests {
		if got := tt.status.Final(); got != tt.want {
			t.Errorf("%s.Final() = %v, want %v", tt.status, got, tt.want)
		}
	}
}

func TestCancelFromCreatedAndPending(t *testing.T) {
	ctx := context.Background()

	t.Run("from created", func(t *testing.T) {
		s, rec := newTestService()
		p, err := s.Create(ctx, CreateInput{MerchantID: "m_1", Amount: money.MustNew(1000, "USD")})
		if err != nil {
			t.Fatal(err)
		}
		canceled, err := s.Cancel(ctx, p.ID)
		if err != nil {
			t.Fatalf("Cancel error: %v", err)
		}
		if canceled.Status != StatusCanceled {
			t.Fatalf("status = %s, want %s", canceled.Status, StatusCanceled)
		}
		if canceled.Version != 2 {
			t.Fatalf("version = %d, want 2", canceled.Version)
		}
		want := "payment.created,payment.canceled"
		if got := strings.Join(rec.events, ","); got != want {
			t.Fatalf("events = %s, want %s", got, want)
		}
	})

	t.Run("from pending", func(t *testing.T) {
		s, rec := newTestService()
		p, err := s.Create(ctx, CreateInput{MerchantID: "m_1", Amount: money.MustNew(1000, "USD")})
		if err != nil {
			t.Fatal(err)
		}
		if _, err := s.Authorize(ctx, p.ID); err != nil {
			t.Fatal(err)
		}
		canceled, err := s.Cancel(ctx, p.ID)
		if err != nil {
			t.Fatalf("Cancel error: %v", err)
		}
		if canceled.Status != StatusCanceled {
			t.Fatalf("status = %s, want %s", canceled.Status, StatusCanceled)
		}
		if canceled.Version != 3 {
			t.Fatalf("version = %d, want 3", canceled.Version)
		}
		want := "payment.created,payment.pending,payment.canceled"
		if got := strings.Join(rec.events, ","); got != want {
			t.Fatalf("events = %s, want %s", got, want)
		}
	})
}

func TestCancelInvalidTransitions(t *testing.T) {
	ctx := context.Background()

	tests := []struct {
		name string
		prep func(t *testing.T, s *Service) string
	}{
		{
			name: "cancel succeeded",
			prep: func(t *testing.T, s *Service) string { return succeeded(t, s, 100).ID },
		},
		{
			name: "cancel declined",
			prep: func(t *testing.T, s *Service) string {
				p, _ := s.Create(ctx, CreateInput{MerchantID: "m", Amount: money.MustNew(100, "USD")})
				p, _ = s.Decline(ctx, p.ID, "test")
				return p.ID
			},
		},
		{
			name: "cancel refunded",
			prep: func(t *testing.T, s *Service) string {
				p := succeeded(t, s, 100)
				p, _, _ = s.Refund(ctx, p.ID, money.MustNew(100, "USD"))
				return p.ID
			},
		},
		{
			name: "cancel already canceled",
			prep: func(t *testing.T, s *Service) string {
				p, _ := s.Create(ctx, CreateInput{MerchantID: "m", Amount: money.MustNew(100, "USD")})
				p, _ = s.Cancel(ctx, p.ID)
				return p.ID
			},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			s, _ := newTestService()
			id := tt.prep(t, s)
