func TestCancelPayment(t *testing.T) {
	a := newTestAPI(t)

	// Cancel from CREATED
	rec := a.do("POST", "/payments", `{"merchant_id":"m_1","amount":"10.00","currency":"USD"}`)
	p := decode[paymentResponse](t, rec)
	rec = a.do("POST", "/payments/"+p.ID+"/cancel", "")
	if rec.Code != http.StatusOK {
		t.Fatalf("cancel created: status %d %s", rec.Code, rec.Body)
	}
	got := decode[paymentResponse](t, rec)
	if got.Status != "CANCELED" {
		t.Fatalf("status %s, want CANCELED", got.Status)
	}

	// Cancel from PENDING
	rec = a.do("POST", "/payments", `{"merchant_id":"m_1","amount":"20.00","currency":"USD"}`)
	p2 := decode[paymentResponse](t, rec)
	rec = a.do("POST", "/payments/"+p2.ID+"/authorize", "")
	if rec.Code != http.StatusOK {
		t.Fatalf("authorize: %d %s", rec.Code, rec.Body)
	}
	rec = a.do("POST", "/payments/"+p2.ID+"/cancel", "")
	if rec.Code != http.StatusOK {
		t.Fatalf("cancel pending: status %d %s", rec.Code, rec.Body)
	}
	got2 := decode[paymentResponse](t, rec)
	if got2.Status != "CANCELED" {
		t.Fatalf("status %s, want CANCELED", got2.Status)
	}

	// Cancel already canceled -> 409
	rec = a.do("POST", "/payments/"+p.ID+"/cancel", "")
	if rec.Code != http.StatusConflict {
		t.Fatalf("cancel canceled: status %d, want 409", rec.Code)
	}
	errBody := decode[errorBody](t, rec)
	if errBody.Error.Code != "invalid_transition" {
		t.Fatalf("code %s, want invalid_transition", errBody.Error.Code)
	}

	// Cancel unknown id -> 404
	rec = a.do("POST", "/payments/pay_nonexistent/cancel", "")
	if rec.Code != http.StatusNotFound {
		t.Fatalf("cancel nonexistent: status %d, want 404", rec.Code)
	}
	errBody = decode[errorBody](t, rec)
	if errBody.Error.Code != "not_found" {
		t.Fatalf("code %s, want not_found", errBody.Error.Code)
	}

	// Cancel succeeded payment -> 409
	pSucceeded := a.createSucceeded("30.00", "USD")
	rec = a.do("POST", "/payments/"+pSucceeded.ID+"/cancel", "")
	if rec.Code != http.StatusConflict {
		t.Fatalf("cancel succeeded: status %d, want 409", rec.Code)
	}
	errBody = decode[errorBody](t, rec)
	if errBody.Error.Code != "invalid_transition" {
		t.Fatalf("code %s, want invalid_transition", errBody.Error.Code)
	}
}

