type recordingSender struct {
	mu    sync.Mutex
	calls []webhook.Delivery
}

func (s *recordingSender) Send(_ context.Context, d webhook.Delivery) (int, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.calls = append(s.calls, d)
	return http.StatusOK, nil
}

func TestCancelWebhookDelivery(t *testing.T) {
	sender := &recordingSender{}
	clk := clock.NewFake(time.Date(2026, 4, 1, 9, 0, 0, 0, time.UTC))
	eps := webhook.StaticEndpoints{"m_1": {URL: "https://merchant.example/hooks", Secret: "s3cret"}}
	hooks := webhook.NewDispatcher(sender, eps, clk, webhook.DefaultPolicy())
	svc := payment.NewService(store.NewMemory(), clk, payment.NewSeqIDs(), hooks, payment.Config{FeeBps: 290})
